    "question": "BOS glukoz, protein ve hücre/klorür düzeylerine göre menenjitlerin ayırıcı tanısı yapılabilir. Bakteriyel, tüberküloz ve aseptik (viral) menenjitte BOS bulguları aşağıdaki şıkların hangisinde doğru verilmiştir?",
