    "answer": "E",
    "open_answer": "Öğretim Üyesi okuyacak,korku, panik anlarında vücudu kaçmaya, hareketlendirmeye yarayan otonom sinir sistemi.,midriyazisi sağlar,t1-l2 hizasında uzanan torakolumbal sistem,vücudun savaş kaç yanıtında rol oynar,geniş etkili otonom sistemdir,diğer bir ismi thoracolumbal sistemdi.,thoracolumbal sistem de denir. sindirimle ilgili şeyler yavaşlar ; dolaşım, solunumu hızlandırır.,sindirim olaylarını yavaşlatıp diğer vücut olaylarını hızlandıran sistem,otonom sinir sisteminin kontrolünde olan bir sistemdir,korku heycan gibi durumlrda aktivitesi artar ve spinal bölgeden çıkar organlara gider,savaş ya da kaç,kalp atımını hızlandırır,",
