    "q_num": 89,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Gülsen Bayrak",
    "question": "I. Kan-beyin bariyerindeki kapiller tipi sürekli tip kapillerdir. II. Kapillerdeki endotelyal hücreler birbirlerine sıkı bağlantılar ile bağlanmışlardır. III. Perisitlerde bulunan Aquaporin-4 (AQP-4) proteini beyin su homeostazisinde görev alır. IV. Pitüiter bezin posterior lobunda bariyer etkisizdir. Yukarıda verilen bilgilerden hangisi ya da hangileri kan-beyin bariyeri için doğru ifadelerdir?",
