    "answer": "E",
    "open_answer": "",
    "explanation": "Doğru Seçenek: E) İşitmede tüy hücresini depolarize eden ana olay -> Klor (Cl-) iyonlarının hücre içine girmesi. Soru kökünde Biyofizik kapsamında yer alan bilgilerden yanlış/istisna olan ifade sorulmaktadır. E seçeneğinde belirtilen 'İşitmede tüy hücresini depolarize eden ana olay -> Klor (Cl-) iyonlarının hücre içine girmesi' ifadesi bilimsel olarak geçersizdir (yanlıştır) ve bu konudaki kurala/mekanizmaya uymaz; dolayısıyla doğru cevap olarak seçilmelidir. Buna karşılık diğer çeldirici seçeneklerde sunulan (A) 'Timpanik zardaki ses basınç değişimi Pz ve zar alanı 55 mm2 ise malleusa etkiyen kuvvet -> 55 x Pz'; B) 'İşitmede tüy hücresi içine girerek hücreyi depolarize eden iyon -> Potasyum (K+)'; C) 'Ses dalgalarının elektriksel sinyallere dönüştürüldüğü yer -> İç kulak, Corti organı'; D) 'Skala media'daki sıvı ve içindeki en fazla bulunan katyon -> Endolenf, K+') ifadeleri ise Biyofizik literatüründe doğru, geçerli ve beklenen bilimsel bilgilerdir. Sınavda sıklıkla yapılan hata bu doğru önermeleri görüp işaretlemektir; ancak soru 'yanlış / istisna' olanı sorguladığından çeldiriciler elenir.",
