    "explanation": "Doğru Seçenek: E) Glandula lacrimalis, glandulae nasales ve glandulae palatinae. N. facialis'ten ganglion geniculi düzeyinde ayrılan N. petrosus major, ganglion pterygopalatinum'a ulaşır. Buradan çıkan postganglionik parasempatik lifler gl. lacrimalis (gözyaşı bezi), burun mukozası bezleri (gl. nasales) ve damak bezlerine (gl. palatinae) sekretomotor uyarı götürür. Hasarında göz kuruluğu gelişir.",
