    "answer": "B",
    "open_answer": "N. ophthalmicus (V1) – N. trigeminus'un dalı.",
    "explanation": "Doğru Seçenek: B) N. ophthalmicus (CN V1). Kornea refleksinin afferent kolunu N. trigeminus'un V1 dalı olan N. ophthalmicus (özellikle n. nasociliaris dalları) oluşturur. Efferent motor kolunu ise gözü kapatan m. orbicularis oculi'yi innerve eden N. facialis (CN VII) oluşturur.",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
