    "answer": "D",
    "open_answer": "Tat duyusu kaybı (Nuc. solitarius hasarı), baş-yüz bölgesinde ağrı-ısı kaybı (Nuc. spinalis n. trigemini), yutma güçlüğü ve ses kısıklığı (Nuc. ambiguus), ipsilateral M. trapezius ve sternocleidomastoideus zayıflığı (Eğer N. accessorius lifleri de etkilendiyse).",
    "explanation": "Doğru Seçenek: D) Tat duyusu kaybı, aynı taraf yüzde ağrı-ısı kaybı, disfaji ve disfoni. Wallenberg (lateral meduller) sendromunda PICA tıkanır. Nucleus ambiguus hasarıyla disfaji ve ses kısıklığı (disfoni), nuc. spinalis n. trigemini hasarıyla ipsilateral yüzde ağrı-ısı kaybı, nuc. solitarius hasarıyla tat duyusu kaybı, inen sempatik liflerin hasarıyla Horner sendromu görülür.",
