    "explanation": "Doğru Seçenek: D) Tractus spinocerebellaris anterior, Tractus spinocerebellaris posterior ve Tractus cuneocerebellaris. Şuuraltı propriyosepsiyon beyinciğe alt ekstremite ve gövdeden Tractus spinocerebellaris anterior ve posterior ile; üst ekstremite ve boyundan ise Tractus cuneocerebellaris ile taşınır. Fasciculus gracilis ve cuneatus ise bilinçli propriyosepsiyonu talamus ve kortekse taşır.",
