    "explanation": "Doğru Seçenek: C) Pineal bez (epifiz) tümörleri. Parinaud sendromu (dorsal mezensefalik sendrom), colliculus superior ve arka komissür basısına bağlı gelişir. En belirgin bulgusu yukarı vertikal bakış felcidir. Çocuk ve genç erişkinlerde en sık pineal bölge tümörlerinde (pinealom, germinom) görülür.",
