    "explanation": "Doğru Seçenek: B) Pacinian (Vater-Pacini) cisimciği. Pacinian (Vater-Pacini) cisimcikleri konsantrik lamelli kapsüle sahip, çok hızlı adapte olan reseptörlerdir ve yüksek frekanslı titreşim (vibrasyon) ile ani basınç değişimlerini algılarlar. Merkel diskleri ve Ruffini cisimcikleri yavaş adapte olurlar.",
